from typing import *
from collections import *

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        dp = [[0] * (k+1) for _ in range(n)]

        # Base case: first subarray
        for i in range(m):
            dp[i][1] = nums[i]

        # Fill the DP table
        for i in range(m, n):
            for j in range(2, k+1):
                dp[i][j] = max(dp[i-m][j-1] + nums[i], dp[i-1][j])

        return max(dp[-1])

from typing import *
class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -float('inf')

        dp = [[0] * m for _ in range(n)]

        # Initialize the first row
        for j in range(m):
            dp[0][j] = nums[j]

        # Fill the DP table
        for i in range(1, n):
            for j in range(m):
                if j == 0:
                    dp[i][j] = dp[i-1][j] + nums[i]
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i-m][j-1]) + nums[i]

        # Find the maximum sum of k non-overlapping subarrays
        max_sum = float('-inf')
        for i in range(n-k+1):
            max_sum = max(max_sum, dp[i+k-1][-1])

        return max_sum

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = len(s)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            if s[i] == 'N':
                prefix_sum[i + 1] = prefix_sum[i] + 1
            elif s[i] == 'S':
                prefix_sum[i + 1] = prefix_sum[i] - 1

        max_dist = 0
        min_prefix_sum = float('inf')
        for i in range(n + 1):
            max_dist = max(max_dist, i - min_prefix_sum)
            if i < n and prefix_sum[i + 1] < min_prefix_sum:
                min_prefix_sum = prefix_sum[i + 1]

        return max_dist

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Initialize variables
        m, n = len(s), len(t)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        # Fill the DP table
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s[i - 1] == t[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        # The maximum value in the bottom-right corner of the DP table is the length of the longest palindrome
        return dp[m][n]
